class Solution {
    private long modPow(long base, long exp, long mod) {
        long res = 1;
        base %= mod;
        while (exp > 0) {
            if (exp % 2 == 1) res = (res * base) % mod;
            base = (base * base) % mod;
            exp /= 2;
        }
        return res;
    }

    public int waysToBuildRooms(int[] prevRoom) {
        long MOD = 1000000007;
        int n = prevRoom.length;
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int i = 1; i < n; i++) adj.get(prevRoom[i]).add(i);

        int[] size = new int[n];
        Arrays.fill(size, 1);
        List<Integer> order = new ArrayList<>();
        Deque<Integer> st = new ArrayDeque<>();
        st.push(0);
        while (!st.isEmpty()) {
            int u = st.pop();
            order.add(u);
            for (int v : adj.get(u)) st.push(v);
        }

        for (int i = n - 1; i >= 0; i--) {
            int u = order.get(i);
            for (int v : adj.get(u)) size[u] += size[v];
        }

        long fact = 1;
        for (int i = 1; i <= n; i++) fact = (fact * i) % MOD;

        long denom = 1;
        for (int s : size) denom = (denom * s) % MOD;

        return (int)((fact * modPow(denom, MOD - 2, MOD)) % MOD);
    }
}

var waysToBuildRooms = function(prevRoom) {
  const MOD = 1000000007n;
  const n = prevRoom.length;
  const adj = Array.from({ length: n }, () => []);
  for (let i = 1; i < n; i++) adj[prevRoom[i]].push(i);

  const size = new Int32Array(n).fill(1);
  const order = [];
  const st = [0];
  while (st.length > 0) {
    const u = st.pop();
    order.push(u);
    for (const v of adj[u]) st.push(v);
  }

  for (let i = n - 1; i >= 0; i--) {
    const u = order[i];
    for (const v of adj[u]) size[u] += size[v];
  }

  function modPow(base, exp) {
    let res = 1n;
    base %= MOD;
    while (exp > 0n) {
      if (exp % 2n === 1n) res = (res * base) % MOD;
      base = (base * base) % MOD;
      exp /= 2n;
    }
    return res;
  }

  let fact = 1n;
  for (let i = 1n; i <= BigInt(n); i++) fact = (fact * i) % MOD;

  let denom = 1n;
  for (let i = 0; i < n; i++) denom = (denom * BigInt(size[i])) % MOD;

  return Number((fact * modPow(denom, MOD - 2n)) % MOD);
};
